CREATE OR REPLACE FUNCTION erp.product_opening_physical_at(p_product_id uuid, p_opening_date date)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'erp', 'public', 'pg_temp'
AS $function$
declare
  p erp.products%rowtype;
  v_day_start timestamptz;
  v_day_end timestamptz;
  v_at timestamptz;
begin
  perform erp.require_internal();
  if p_opening_date is null then raise exception 'Tanggal opening wajib diisi'; end if;
  select * into p from erp.products where id=p_product_id;
  if p.id is null then raise exception 'SKU opening tidak ditemukan'; end if;
  v_day_start:=p_opening_date::timestamp at time zone 'Asia/Jakarta';
  v_day_end:=(p_opening_date+1)::timestamp at time zone 'Asia/Jakarta';

  -- Legacy physical stock may remain after identity expiry, so effective_to does
  -- not invalidate the old SKU for opening. But a version cannot be placed before
  -- the first instant it ever became effective on the opening day.
  v_at:=greatest(v_day_start,p.effective_from);
  if v_at>=v_day_end then
    raise exception 'Versi SKU % belum pernah berlaku pada tanggal opening %. Pilih SKU yang sudah berlaku sebelum/di tanggal opening tersebut.',p.sku,p_opening_date;
  end if;
  return v_at;
end$function$

private_hpp.definition:
CREATE OR REPLACE FUNCTION cp7_finance.read_opening_hpp_diagnostic_v1(p_item_id uuid, p_opening_date date)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  i erp.opening_balance_items%rowtype;
  v_price numeric(20,6);
  v_hpp numeric(20,6);
  v_asof timestamptz;
begin
  perform erp.require_internal();
  select * into i from erp.opening_balance_items where id=p_item_id;
  if i.id is null or i.balance_type<>'FINISHED_GOODS' then raise exception 'Opening FG item tidak ditemukan'; end if;

  -- Opening date is a business date, while versioned SKU identity is timestamped.
  -- Use the first valid instant for this SKU on that opening date so a same-day
  -- effective identity is not incorrectly treated as 'not yet existing at midnight'.
  v_asof:=erp.product_opening_physical_at(i.product_id,p_opening_date);

  if i.hpp_input_method='PRICE_PERCENT' then
    if i.hpp_percent_of_price is null or i.hpp_percent_of_price<=0 or i.hpp_percent_of_price>1000 then
      raise exception 'Persentase HPP dari harga jual wajib >0 dan masuk akal untuk opening FG';
    end if;
    v_price:=erp.resolve_product_price_at(i.product_id,v_asof);
    if v_price is null then
      raise exception 'Harga jual produk belum tersedia pada waktu opening %. Isi harga jual historis/cutover atau gunakan HPP manual.',v_asof;
    end if;
    v_hpp:=round(v_price*i.hpp_percent_of_price/100.0,6);
    return v_hpp;
  end if;

  v_hpp:=coalesce(i.unit_cost_snapshot,0);
  return v_hpp;
end;
$function$

